<?php
namespace App\Console\Commands;use App\Models\BillingStatement;use App\Models\Organization;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;class PrepareBillingStatements extends Command{protected$signature='billing:prepare {--month=}';protected$description='Oppretter månedlige fakturagrunnlag for abonnement og SMS-forbruk';public function handle():int{$period=$this->option('month')?now()->parse($this->option('month').'-01'):today()->subMonth()->startOfMonth();$start=$period->copy()->startOfMonth();$end=$period->copy()->endOfMonth();$unit=(int)config('services.sms.billing_unit_price_cents',0);$count=0;Organization::whereIn('subscription_status',['active','trialing'])->chunkById(100,function($organizations)use($start,$end,$unit,&$count){foreach($organizations as$organization){$sms=(int)DB::table('usage_events')->where('organization_id',$organization->id)->where('type','sms')->whereBetween('occurred_at',[$start,$end->copy()->endOfDay()])->sum('quantity');$subscription=11900;$smsTotal=$sms*$unit;$gross=$subscription+$smsTotal;$discount=$organization->billing_discount_percent?(int)round($gross*((int)$organization->billing_discount_percent/100)):0;if($organization->billing_discount_ends_at&&$organization->billing_discount_ends_at->lt($start))$discount=0;BillingStatement::updateOrCreate(['organization_id'=>$organization->id,'period_start'=>$start->toDateString()],['public_id'=>(string)Str::uuid(),'period_end'=>$end->toDateString(),'subscription_cents'=>$subscription,'sms_quantity'=>$sms,'sms_unit_price_cents'=>$unit,'sms_total_cents'=>$smsTotal,'discount_cents'=>$discount,'total_cents'=>max(0,$gross-$discount),'status'=>'ready','finalized_at'=>now()]);$count++;}});$this->info($count.' fakturagrunnlag klare for '.$start->format('m.Y').'.');return self::SUCCESS;}}
